def describe_acme_widgets() -> dict:
    """Describe what acme widgets contains: entities, fields, labels, filter modes and limits. Call this first.
    """
    result = dict(_SCHEMA)
    result["ok"] = True
    return result


def query_widget(field: Optional[str] = None, value: Optional[str] = None, match: str = "equals", fields: Optional[list[str]] = None, limit: int = 20, offset: int = 0) -> dict:
    """Query widgets by one field using equals, contains or startsWith matching. Returns at most 50 rows per call.

    limit is clamped to the range 1 to 50; larger values are reduced, not rejected.

    Give both field and value to filter; give neither to list rows. Call the describe tool to see the fields.

    Args:
        field: Field to filter on.
        value: Value to match (text or number).
        match: equals, contains or startsWith (case-insensitive).
        fields: Optional list of field names to return (at most 12; unknown names are ignored).
        limit: Rows to return (1 to 50).
        offset: Rows to skip, for paging.
    """
    try:
        problem = _query_problem(_ALLOWED["widget"], "describe_acme_widgets", field, value, match)
        if problem is not None:
            return problem
        sel = _select_fields(fields, _ALLOWED["widget"], _DEFAULT["widget"])
        limit = _clamp(limit, 1, 50)
        offset = _clamp(offset, 0, 1000000000)
        rows = _load_rows()
        if field is not None:
            rows = [row for row in rows if _match(row.get(field), match, value)]
        total = len(rows)
        rows = rows[offset : offset + min(limit, MAX_RESPONSE_ITEMS)]
        if not rows:
            return _no_results("widget", "Try a broader value or another match mode.")
        results = [_project(row, sel) for row in rows]
        return {"ok": True, "results": results, "count": len(results), "total_matches": total, "offset": offset, "limit": limit}
    except _Fail as exc:
        return _fail(exc)
    except Exception:
        return _err("internal", _INTERNAL_MESSAGE)


